import{_ as t,o as i,c as o,a2 as s}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"Quick Panel Settings","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/quick-panel.md","filePath":"user-guide/settings/quick-panel.md","lastUpdated":1787752921000}'),n={name:"user-guide/settings/quick-panel.md"};function a(r,e,l,d,c,g){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="quick-panel-settings" tabindex="-1">Quick Panel Settings <a class="header-anchor" href="#quick-panel-settings" aria-label="Permalink to &quot;Quick Panel Settings&quot;">​</a></h1><p>The <strong>Quick Panel</strong> is a floating workspace designed for high-frequency file retrieval, project context management, and drag-and-drop file staging. When invoked, it docks automatically to the bottom-right corner of the active foreground window, allowing you to access and stage files without switching contexts.</p><h2 id="_1-core-architecture-global-toggle" tabindex="-1">1. Core Architecture &amp; Global Toggle <a class="header-anchor" href="#_1-core-architecture-global-toggle" aria-label="Permalink to &quot;1. Core Architecture &amp; Global Toggle&quot;">​</a></h2><ul><li><strong>Enable Quick Panel</strong>: Master switch; when disabled, the hotkey does not intercept input.</li><li><strong>Summon Hotkey</strong>: Default <strong><code>Ctrl+F2</code></strong> (customizable under <a href="./hotkeys-page.html"><strong>Settings → Hotkeys</strong></a>).</li><li><strong>Smart Docking &amp; Sizing</strong>: Sized by default to half the width and height of the host window (constrained to a minimum of <code>280 × 200px</code> to guarantee legibility). If a Lertaro window is already focused, summon requests are ignored to avoid stacking; pressing the hotkey while the panel is open closes it.</li><li><strong>Quick Jump Integration</strong>: While open, the physical folder of the active group is tracked as the working directory. Pressing Quick Jump (<code>Ctrl+G</code>) in file dialogs navigates straight there.</li></ul><h2 id="_2-workspaces" tabindex="-1">2. Workspaces <a class="header-anchor" href="#_2-workspaces" aria-label="Permalink to &quot;2. Workspaces&quot;">​</a></h2><p>Workspaces organize folders by project or task:</p><ul><li><strong>Workspace Management</strong>: The left list manages workspaces (<strong>New</strong>, <strong>Duplicate</strong>, <strong>Delete</strong>), supporting drag-and-drop reordering that maps directly to the horizontal tab bar.</li><li><strong>Properties</strong>: <ul><li><strong>Name</strong>: Text shown on the tab header (falls back to a localized default name if blank).</li><li><strong>Enable Switch</strong>: Toggles visibility in the tab bar. Clicking the <strong>×</strong> button on a tab in the panel hides it; re-enable it here.</li></ul></li></ul><p>Selected workspaces are configured across two tabs: <strong>Sources</strong> and <strong>Applications</strong>.</p><h2 id="_3-sources-configuration" tabindex="-1">3. Sources Configuration <a class="header-anchor" href="#_3-sources-configuration" aria-label="Permalink to &quot;3. Sources Configuration&quot;">​</a></h2><p>Each source represents a distinct group within the workspace:</p><ul><li><strong>Add Folder</strong>: Selects the target directory on disk.</li><li><strong>Display Mode</strong>: <ul><li><strong>Recent modified files</strong> — Queries the memory index in sub-milliseconds to show recently changed files (newest first).</li><li><strong>All files, newest first</strong> — Shows all files sorted by last modified date in descending order.</li><li><strong>All files, by name</strong> — Functions as a pinned shortcut launcher.</li></ul></li><li><strong>Include Subfolders</strong>: Recursively includes descendant files when checked.</li><li><strong>Accept Dropped Files</strong>: Allows dragging files, folders, or web images from other windows into this group. Lertaro executes a native Windows copy with conflict prompts and undo support.</li><li><strong>Filtering Rules</strong>: Uses wildcard patterns or search-syntax <code>@</code> filters to constrain displayed file types (e.g. <code>*.mp4;*.mkv</code>, <code>*.lnk;:@doc;:@img</code>, or <code>*.lnk;:@doc|img</code>).</li><li><strong>Max Count &amp; Time Limit</strong>: Limits total items displayed (0 for unlimited) or restricts results to files modified within N minutes.</li><li><strong>Detailed List vs. Thumbnail Tiles</strong>: Choose between a compact list view or thumbnail grid (tiles scale proportionally while preserving image aspect ratios).</li></ul><h2 id="_4-plugin-tabs" tabindex="-1">4. Plugin Tabs <a class="header-anchor" href="#_4-plugin-tabs" aria-label="Permalink to &quot;4. Plugin Tabs&quot;">​</a></h2><p>Plugins can register global dynamic lists into the Quick Panel. The CoreExtensions plugin provides five built-in tabs:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Plugin Tab</th><th style="text-align:left;">Contents</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Favorites</strong></td><td style="text-align:left;">Pinned starred items; URLs open directly in your default browser.</td></tr><tr><td style="text-align:left;"><strong>History</strong></td><td style="text-align:left;">Items and applications recently launched through Lertaro.</td></tr><tr><td style="text-align:left;"><strong>Windows History</strong></td><td style="text-align:left;">Resolves Windows Recent Documents into physical file targets.</td></tr><tr><td style="text-align:left;"><strong>Last Directory</strong></td><td style="text-align:left;">Tracks the folder you just navigated in File Explorer or a file dialog.</td></tr><tr><td style="text-align:left;"><strong>Recent Files</strong></td><td style="text-align:left;">Aggregates the newest files across all configured folders using the memory index.</td></tr></tbody></table><p>Each plugin tab can be enabled/disabled and configured with List or Tile views.</p><h2 id="_5-application-binding-dedicated-blacklist" tabindex="-1">5. Application Binding &amp; Dedicated Blacklist <a class="header-anchor" href="#_5-application-binding-dedicated-blacklist" aria-label="Permalink to &quot;5. Application Binding &amp; Dedicated Blacklist&quot;">​</a></h2><ul><li><strong>Applications</strong>: Associate workspace tabs with foreground process names (e.g. <code>chrome.exe</code> or <code>devenv.exe</code>). Summoning the Quick Panel over those apps switches directly to that workspace.</li><li><strong>Quick Panel Only Blacklist</strong>: Configure apps where the Quick Panel should not appear. This list is <strong>additive</strong> to the global blacklist.</li></ul><h2 id="_6-panel-navigation-guide" tabindex="-1">6. Panel Navigation Guide <a class="header-anchor" href="#_6-panel-navigation-guide" aria-label="Permalink to &quot;6. Panel Navigation Guide&quot;">​</a></h2><ul><li><strong>Live Fuzzy Filtering</strong>: A search box in the top-right corner supports fzf fuzzy matching and pinyin aliases to filter the active workspace.</li><li><strong>Keyboard Navigation</strong>: Arrow keys navigate seamlessly across group boundaries; press <code>Enter</code> to open the highlighted item.</li><li><strong>Tab Switching</strong>: Press <code>Ctrl</code> + <code>1</code>–<code>9</code> to jump directly across workspace and plugin tabs.</li><li><strong>QuickLook &amp; Pinning</strong>: Press <code>Alt+P</code> to open the docked instant preview; press <code>Ctrl+T</code> to pin the panel so it stays open when focus is lost.</li></ul>',19)])])}const p=t(n,[["render",a]]);export{h as __pageData,p as default};
